exercises.solution:
using System.Threading.Tasks;

var t = Task.Run(async () => { await Task.Delay(100); SayHello(); });
Console.WriteLine("main done");
t.GetAwaiter().GetResult();

static void SayHello() => Console.WriteLine("Hello!");

using System.Threading.Channels;
using System.Threading.Tasks;

var ch = Channel.CreateUnbounded<string>();
var worker = Task.Run(async () => { await ch.Writer.WriteAsync("ping"); ch.Writer.Complete(); });
Console.WriteLine(await ch.Reader.ReadAsync());
await worker;

using System.Threading.Channels;

var ch = Channel.CreateBounded<int>(2);
ch.Writer.TryWrite(10);
ch.Writer.TryWrite(20);
ch.Writer.Complete();
Console.Write(ch.Reader.ReadAsync().AsTask().GetAwaiter().GetResult());
Console.Write(" ");
Console.Write(ch.Reader.ReadAsync().AsTask().GetAwaiter().GetResult());

using System.Threading.Channels;
using System.Threading.Tasks;

var ch = Channel.CreateUnbounded<string>();
var worker = Task.Run(async () => { await Task.Delay(10); await ch.Writer.WriteAsync("from ch1"); ch.Writer.Complete(); });
Console.Write(await ch.Reader.ReadAsync());
await worker;

using System.Threading.Channels;
using System.Threading.Tasks;

var ch = Channel.CreateUnbounded<int>();
var prod = Task.Run(async () => { foreach (var n in new[] {1,2,3}) await ch.Writer.WriteAsync(n); ch.Writer.Complete(); });
await foreach (var n in ch.Reader.ReadAllAsync()) Console.WriteLine(n);
await prod;

using System.Threading.Tasks;
using System.Collections.Generic;

var list = new List<string>();
var gate = new object();
Task.Run(() => { lock (gate) list.Add("hello"); }).Wait();
Task.Run(() => { lock (gate) list.Add("world"); }).Wait();
list.Sort();
foreach (var s in list) Console.WriteLine(s);

using System.Threading.Tasks;

for (var i = 1; i <= 3; i++) { var j = i; Task.Run(() => Console.WriteLine(j)).Wait(); }
Console.WriteLine("done");
